>>   		now = FIELD_GET(MSMON___VALUE, now32);
>>   
>> @@ -1371,7 +1380,9 @@ static void __ris_msmon_read(void *arg)
>>   			else
>>   				now = FIELD_GET(MSMON___L_VALUE, now);
>>   		} else {
>> -			mpam_read_monsel_reg(msc, MBWU, &now32);
>> +			ret = mpam_read_monsel_reg(msc, MBWU, &now32);
>> +			if (ret)
